const $=s=>document.querySelector(s),access=$('#access'),register=$('#register'),portal=$('#portal'),loginForm=$('#login-form'),codeForm=$('#code-form'),orderForm=$('#order-form');let products=[];
const digits=v=>String(v||'').replace(/\D/g,'');const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);const msg=(el,text,type='')=>{el.textContent=text;el.className=`message ${type}`};
async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.message||'Não foi possível concluir.');return data}
function mask(input,kind){input.addEventListener('input',()=>{const n=digits(input.value).slice(0,kind==='cpf'?11:14);input.value=kind==='cpf'?n.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/(\d{3})\.(\d{3})\.(\d{3})(\d)/,'$1.$2.$3-$4'):n.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d)/,'$1-$2')})}
mask($('#register-form').elements.cpf,'cpf');mask($('#register-form').elements.cnpj,'cnpj');mask(orderForm.elements.cpf,'cpf');mask(orderForm.elements.cnpj,'cnpj');orderForm.elements.phone.addEventListener('input',e=>{const n=digits(e.target.value).slice(0,11);e.target.value=n.length>10?n.replace(/^(\d{2})(\d{5})(\d*)$/,'($1) $2-$3'):n.replace(/^(\d{2})(\d{4})(\d*)$/,'($1) $2-$3')});
$('#open-register').onclick=()=>{access.hidden=true;register.hidden=false};$('#back-login').onclick=()=>{register.hidden=true;access.hidden=false};
$('#register-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;msg($('#register-message'),'Enviando cadastro…');try{const data=await api('/api/reseller/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});msg($('#register-message'),data.message,'success');f.reset()}catch(err){msg($('#register-message'),err.message,'error')}finally{b.disabled=false}});
loginForm.addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;msg($('#auth-message'),'Enviando código…');try{const data=await api('/api/reseller/auth/request-code',{method:'POST',body:JSON.stringify({email:loginForm.elements.email.value})});msg($('#auth-message'),data.message,'success');loginForm.hidden=true;loginForm.style.display='none';codeForm.hidden=false;codeForm.style.display='grid';codeForm.elements.code.focus()}catch(err){msg($('#auth-message'),err.message,'error')}finally{b.disabled=false}});
codeForm.addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{await api('/api/reseller/auth/verify-code',{method:'POST',body:JSON.stringify({email:loginForm.elements.email.value,code:codeForm.elements.code.value})});await loadPortal()}catch(err){msg($('#auth-message'),err.message,'error')}finally{b.disabled=false}});
async function loadPortal(){const data=await api('/api/reseller/dashboard');products=data.products;access.hidden=true;register.hidden=true;portal.hidden=false;$('#logout').hidden=false;$('#partner-name').textContent=`${data.user.accounting_name} · acesso de ${data.user.name}`;renderProducts();$('#orders').innerHTML=data.orders.length?data.orders.map(o=>`<article class="order"><strong>${o.protocol}</strong><span>${o.holder}</span><small>${o.product_title} · ${money(o.price_cents)}<br>${o.appointment_date.split('-').reverse().join('/')} às ${o.appointment_time}</small></article>`).join(''):'<p>Nenhum agendamento criado ainda.</p>'}
function renderProducts(){const person=orderForm.elements.person.value,items=products.filter(p=>p.person===person),select=orderForm.elements.certificate;select.replaceChildren(...items.map(p=>new Option(`${p.title} · ${money(p.price_cents)}`,p.product_id)));updatePrice();document.querySelectorAll('.pj').forEach(el=>{el.hidden=person!=='pj';const input=el.querySelector('input');if(input)input.required=person==='pj'})}function updatePrice(){const p=products.find(x=>x.product_id===orderForm.elements.certificate.value);$('#price').textContent=p?money(p.price_cents):'—'}orderForm.elements.person.onchange=renderProducts;orderForm.elements.certificate.onchange=updatePrice;
const now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;orderForm.elements.date.min=today;orderForm.elements.birth.max=today;async function availability(){const date=orderForm.elements.date.value,time=orderForm.elements.time;time.disabled=true;time.replaceChildren(new Option('Consultando…',''));if(!date)return;try{const data=await api(`/api/availability?date=${encodeURIComponent(date)}&mode=${encodeURIComponent(orderForm.elements.mode.value)}`);time.replaceChildren(new Option('Escolha um horário',''),...data.slots.map(s=>new Option(s,s)));time.disabled=!data.slots.length}catch{time.replaceChildren(new Option('Indisponível',''))}}orderForm.elements.date.onchange=availability;orderForm.elements.mode.onchange=availability;
orderForm.elements.zip.addEventListener('blur',async()=>{const zip=digits(orderForm.elements.zip.value);if(zip.length!==8)return;try{const r=await fetch(`https://brasilapi.com.br/api/cep/v1/${zip}`),a=await r.json();orderForm.elements.street.value=a.street||'';orderForm.elements.district.value=a.neighborhood||'';orderForm.elements.city.value=a.city||'';orderForm.elements.state.value=a.state||''}catch{}});
orderForm.addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type="submit"]');b.disabled=true;msg($('#order-message'),'Criando agendamento…');try{const result=await api('/api/reseller/orders',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(orderForm)))});$('#protocol').textContent=result.protocol;if(result.payment){$('#pix-amount').textContent=money(result.payment.amountCents);$('#pix-code').value=result.payment.copyPaste;$('#qr').replaceChildren();new QRCode($('#qr'),{text:result.payment.copyPaste,width:210,height:210,colorDark:'#031127',colorLight:'#fff',correctLevel:QRCode.CorrectLevel.M})}else{$('#pix-amount').textContent='PIX será preparado pela Agilize';$('#pix-code').value=''}$('#success').showModal();orderForm.reset();orderForm.elements.date.min=today;await loadPortal();msg($('#order-message'),'Agendamento criado com sucesso.','success')}catch(err){msg($('#order-message'),err.message,'error')}finally{b.disabled=false}});
$('#copy-pix').onclick=async()=>{const code=$('#pix-code').value;if(!code)return;try{await navigator.clipboard.writeText(code)}catch{$('#pix-code').select();document.execCommand('copy')}$('#copy-pix').textContent='PIX copiado'};$('#success .close').onclick=()=>$('#success').close();$('#logout').onclick=async()=>{await api('/api/reseller/auth/logout',{method:'POST'});location.reload()};
api('/api/reseller/session').then(loadPortal).catch(()=>{});
